<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php'; require __DIR__.'/app/customer.php';
$rawCode=strtoupper($_GET['code']??($_POST['code']??''));$nextCode=preg_match('/^ED[0-9]{8}$/',$rawCode)?$rawCode:'';
$error='';
if(customer_logged_in()){$go=(($_GET['next']??'')==='activate'&&$nextCode!=='')?'activate-plaque.php?code='.rawurlencode($nextCode):'customer-dashboard.php';header('Location: '.$go);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$q=db()->prepare("SELECT id,name,password_hash FROM customer_accounts WHERE email=? AND status='active' LIMIT 1");$q->execute([$email]);$a=$q->fetch();if($a&&password_verify((string)($_POST['password']??''),$a['password_hash'])){session_regenerate_id(true);unset($_SESSION['admin_id'],$_SESSION['reseller_id']);$_SESSION['customer_id']=$a['id'];$_SESSION['customer_name']=$a['name'];$go=(($_POST['next']??'')==='activate'&&$nextCode!=='')?'activate-plaque.php?code='.rawurlencode($nextCode):'customer-dashboard.php';header('Location: '.$go);exit;}$error='E-mail ou senha inválidos.';}
layout_start('Entrar na conta');
?><section class="narrow"><span class="eyebrow">ÁREA DO CLIENTE</span><h1>Bem-vindo de volta</h1><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><form method="post" class="panel"><input type="hidden" name="next" value="<?=e($_GET['next']??($_POST['next']??''))?>"><input type="hidden" name="code" value="<?=e($nextCode)?>"><?=client_csrf_field()?><label>E-mail<input type="email" name="email" required autocomplete="username"></label><label>Senha<input type="password" name="password" required autocomplete="current-password"></label><button>Entrar</button><p style="margin-top:15px"><a href="forgot-password.php?type=customer">Esqueci minha senha</a></p><p>Não tem conta? <a href="customer-register.php?next=<?=e($_GET['next']??'')?>&amp;code=<?=e($nextCode)?>">Criar minha conta</a></p></form></section><?php layout_end(); ?>